void insertion_sort(int values[], size_t length) {
    for (size_t i = 1; i < length; ++i) {
        int key = values[i];
        size_t j = i;
        while (j > 0 && values[j - 1] > key) {
            values[j] = values[j - 1];
            --j;
        }
        values[j] = key;
    }
}

